PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?maxPolarity ?minPolarity
WHERE {
  { SELECT (MAX(xsd:float(?s1_polarityValue)) AS ?maxPolarity) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?a1_lemmaType { lila:Lemma lila:Hypolemma }
        ?a1_lemma a ?a1_lemmaType .
        ?a1_lemma ontolex:writtenRep ?a1_wr .
        FILTER(STR(?a1_wr) = "coltura") .
      }
      ?s1_sentixLemma ontolex:canonicalForm ?a1_lemma ;
                   marl:hasPolarity ?s1_polarity ;
                   marl:hasPolarityValue ?s1_polarityValue .
      BIND(STRAFTER(STR(?s1_polarity), "#") AS ?s1_polarityLabel)
    }
  }
  { SELECT (MIN(xsd:float(?s2_polarityValue)) AS ?minPolarity) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?a2_lemmaType { lila:Lemma lila:Hypolemma }
        ?a2_lemma a ?a2_lemmaType .
        ?a2_lemma ontolex:writtenRep ?a2_wr .
        FILTER(STR(?a2_wr) = "coltura") .
      }
      ?s2_sentixLemma ontolex:canonicalForm ?a2_lemma ;
                   marl:hasPolarity ?s2_polarity ;
                   marl:hasPolarityValue ?s2_polarityValue .
      BIND(STRAFTER(STR(?s2_polarity), "#") AS ?s2_polarityLabel)
    }
  }
}

