PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT (?a_wr AS ?wr) (?t_parWR AS ?parWR) (?maxPolarity AS ?maxValue)
WHERE {
  { SELECT ?a_wr ?t_parWR (MAX(xsd:float(?s_polarityValue)) AS ?maxPolarity) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?a_lemmaType { lila:Lemma lila:Hypolemma }
        ?a_lemma a ?a_lemmaType .
        ?a_lemma lila:hasPOS lila:adjective .
        ?a_lemma ontolex:writtenRep ?a_wr .
        FILTER(REGEX(STR(?a_wr), "noso$")) .
      }
      ?t_itToParEntry ontolex:canonicalForm ?a_lemma ;
                   vartrans:translatableAs ?t_parEntry .
      ?t_parEntry ontolex:canonicalForm ?t_parLemma .
      ?t_parLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
               ontolex:writtenRep ?t_parWR .
      ?s_sentixLemma ontolex:canonicalForm ?a_lemma ;
                   marl:hasPolarity ?s_polarity ;
                   marl:hasPolarityValue ?s_polarityValue .
      BIND(STRAFTER(STR(?s_polarity), "#") AS ?s_polarityLabel)
    }
    GROUP BY ?a_wr ?t_parWR
  }
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT (?a_wr AS ?wr) (?e_emotionLabel AS ?emotionLabel)
WHERE {
  GRAPH <http://liita.it/data> {
    VALUES ?a_lemmaType { lila:Lemma lila:Hypolemma }
    ?a_lemma a ?a_lemmaType .
    ?a_lemma lila:hasPOS lila:adjective .
    ?a_lemma ontolex:writtenRep ?a_wr .
  }
  ?e_elitaLemma ontolex:canonicalForm ?a_lemma .
  ?e_elitaLemma elita:HasEmotion ?e_emotion .
  VALUES ?e_emotion { elita:Amore elita:Disgusto }
  ?e_emotion rdfs:label ?e_emotionLabel .
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT (?u_wr AS ?wr)
WHERE {
  {
    GRAPH <http://liita.it/data> {
      VALUES ?a_lemmaType { lila:Lemma lila:Hypolemma }
      ?u_lemma a ?a_lemmaType .
      ?u_lemma lila:hasPOS lila:noun .
      ?u_lemma ontolex:writtenRep ?u_wr .
      FILTER(REGEX(STR(?u_wr), "iuto$")) .
    }
  }
  UNION
  {
    GRAPH <http://liita.it/data> {
      VALUES ?b_lemmaType { lila:Lemma lila:Hypolemma }
      ?u_lemma a ?b_lemmaType .
      ?u_lemma lila:hasPOS lila:adjective .
      ?u_lemma ontolex:writtenRep ?u_wr .
      FILTER(REGEX(STR(?u_wr), "iuto$")) .
    }
  }
  ?s_sentixLemma ontolex:canonicalForm ?u_lemma ;
               marl:hasPolarity ?s_polarity ;
               marl:hasPolarityValue ?s_polarityValue .
  BIND(STRAFTER(STR(?s_polarity), "#") AS ?s_polarityLabel)
  FILTER(xsd:float(?s_polarityValue) < 0)
}

