PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT (?u_wordRel AS ?wordRel) (?u_itLemmaString AS ?itLemmaString)
WHERE {
  {
    SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
      ?u_seedWord a ontolex:Word ;
                lexinfo:partOfSpeech [ rdfs:label ?a_posLabel ] ;
                ontolex:canonicalForm [ ontolex:writtenRep ?a_seedForm ] ;
                ontolex:sense ?a_seedSense .
      FILTER(str(?a_seedForm) = "capinera") .
      ?u_senseRel lexinfo:hyponym ?a_seedSense .
      OPTIONAL { ?u_senseRel skos:definition ?u_definition . }
      ?u_wordRel ontolex:sense ?u_senseRel ;
               ontolex:canonicalForm ?a_formRel .
      ?a_formRel ontolex:writtenRep ?u_itLemmaString .
    }
  }
  UNION
  {
    SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
      ?u_seedWord a ontolex:Word ;
                lexinfo:partOfSpeech [ rdfs:label ?b_posLabel ] ;
                ontolex:canonicalForm [ ontolex:writtenRep ?b_seedForm ] ;
                ontolex:sense ?b_seedSense .
      FILTER(str(?b_seedForm) = "capinera") .
      ?u_senseRel lexinfo:partMeronym ?b_seedSense .
      OPTIONAL { ?u_senseRel skos:definition ?u_definition . }
      ?u_wordRel ontolex:sense ?u_senseRel ;
               ontolex:canonicalForm ?b_formRel .
      ?b_formRel ontolex:writtenRep ?u_itLemmaString .
    }
  }
}

