  ?b_itEntry ontolex:canonicalForm ?b_liitaLemma .
  ?b_liitaLemma ontolex:writtenRep ?b_itLemmaString .
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
