      GRAPH <http://liita.it/data> {
        VALUES ?a2_lemmaType { lila:Lemma lila:Hypolemma }
        ?a2_lemma a ?a2_lemmaType .
        ?a2_lemma ontolex:writtenRep ?a2_wr .
      }
      ?e2_elitaLemma ontolex:canonicalForm ?a2_lemma .
      ?e2_elitaLemma elita:HasEmotion ?e2_emotion .
      ?e2_emotion rdfs:label ?e1_emotionLabel .
      ?s2_sentixLemma ontolex:canonicalForm ?a2_lemma ;
                   marl:hasPolarity ?s2_polarity ;
                   marl:hasPolarityValue ?s2_polarityValue .
      BIND(STRAFTER(STR(?s2_polarity), "#") AS ?s2_polarityLabel)
    }
    GROUP BY ?e1_emotionLabel
  }
  { SELECT ?e1_emotionLabel (COUNT(DISTINCT ?a3_lemma) AS ?withSicilian) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?a3_lemmaType { lila:Lemma lila:Hypolemma }
        ?a3_lemma a ?a3_lemmaType .
        ?a3_lemma ontolex:writtenRep ?a3_wr .
      }
      ?e3_elitaLemma ontolex:canonicalForm ?a3_lemma .
      ?e3_elitaLemma elita:HasEmotion ?e3_emotion .
      ?e3_emotion rdfs:label ?e1_emotionLabel .
      ?t3_itToSicEntry ontolex:canonicalForm ?a3_lemma ;
                   vartrans:translatableAs ?t3_sicEntry .
      ?t3_sicEntry ontolex:canonicalForm ?t3_sicLemma .
      ?t3_sicLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
               ontolex:writtenRep ?t3_sicWR .
    }
    GROUP BY ?e1_emotionLabel
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT (?p_pos AS ?pos) ?lemmaCount ?withSicilian ?withParmigiano
WHERE {
  { SELECT ?p_pos (COUNT(DISTINCT ?a_lemma) AS ?lemmaCount) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?a_lemmaType { lila:Lemma lila:Hypolemma }
        ?a_lemma a ?a_lemmaType .
        ?a_lemma ontolex:writtenRep ?a_wr .
      }
      GRAPH <http://liita.it/data> {
        ?a_lemma lila:hasPOS ?p_pos .
      }
    }
    GROUP BY ?p_pos
  }
  { SELECT ?p_pos (COUNT(DISTINCT ?c_lemma) AS ?withSicilian) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?c_lemmaType { lila:Lemma lila:Hypolemma }
        ?c_lemma a ?c_lemmaType .
        ?c_lemma ontolex:writtenRep ?c_wr .
      }
      GRAPH <http://liita.it/data> {
        ?c_lemma lila:hasPOS ?p_pos .
      }
      ?s_itToSicEntry ontolex:canonicalForm ?c_lemma ;
                   vartrans:translatableAs ?s_sicEntry .
      ?s_sicEntry ontolex:canonicalForm ?s_sicLemma .
      ?s_sicLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
               ontolex:writtenRep ?s_sicWR .
    }
    GROUP BY ?p_pos
  }
  { SELECT ?p_pos (COUNT(DISTINCT ?e_lemma) AS ?withParmigiano) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?e_lemmaType { lila:Lemma lila:Hypolemma }
        ?e_lemma a ?e_lemmaType .
        ?e_lemma ontolex:writtenRep ?e_wr .
      }
      GRAPH <http://liita.it/data> {
        ?e_lemma lila:hasPOS ?p_pos .
      }
      ?t_itToParEntry ontolex:canonicalForm ?e_lemma ;
                   vartrans:translatableAs ?t_parEntry .
      ?t_parEntry ontolex:canonicalForm ?t_parLemma .
      ?t_parLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
               ontolex:writtenRep ?t_parWR .
    }
    GROUP BY ?p_pos
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
