PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT (?s1_polarityLabel AS ?polarityLabel) ?lemmaCount ?withEmotion ?withParmigiano
WHERE {
  { SELECT ?s1_polarityLabel (COUNT(DISTINCT ?a1_lemma) AS ?lemmaCount) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?a1_lemmaType { lila:Lemma lila:Hypolemma }
        ?a1_lemma a ?a1_lemmaType .
