      ?s1_sentixLemma ontolex:canonicalForm ?a1_lemma ;
                   marl:hasPolarity ?s1_polarity ;
                   marl:hasPolarityValue ?s1_polarityValue .
      BIND(STRAFTER(STR(?s1_polarity), "#") AS ?s1_polarityLabel)
    }
    GROUP BY ?s1_polarityLabel
  }
  { SELECT ?s1_polarityLabel (COUNT(DISTINCT ?a2_lemma) AS ?withEmotion) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?a2_lemmaType { lila:Lemma lila:Hypolemma }
        ?a2_lemma a ?a2_lemmaType .
        ?a2_lemma ontolex:writtenRep ?a2_wr .
      }
      ?s2_sentixLemma ontolex:canonicalForm ?a2_lemma ;
                   marl:hasPolarity ?s2_polarity ;
                   marl:hasPolarityValue ?s2_polarityValue .
      BIND(STRAFTER(STR(?s2_polarity), "#") AS ?s1_polarityLabel)
      ?e2_elitaLemma ontolex:canonicalForm ?a2_lemma .
      ?e2_elitaLemma elita:HasEmotion ?e2_emotion .
      ?e2_emotion rdfs:label ?e2_emotionLabel .
    }
    GROUP BY ?s1_polarityLabel
  }
  { SELECT ?s1_polarityLabel (COUNT(DISTINCT ?a3_lemma) AS ?withParmigiano) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?a3_lemmaType { lila:Lemma lila:Hypolemma }
        ?a3_lemma a ?a3_lemmaType .
        ?a3_lemma ontolex:writtenRep ?a3_wr .
      }
      ?s3_sentixLemma ontolex:canonicalForm ?a3_lemma ;
                   marl:hasPolarity ?s3_polarity ;
                   marl:hasPolarityValue ?s3_polarityValue .
      BIND(STRAFTER(STR(?s3_polarity), "#") AS ?s1_polarityLabel)
      ?p3_itToParEntry ontolex:canonicalForm ?a3_lemma ;
                   vartrans:translatableAs ?p3_parEntry .
      ?p3_parEntry ontolex:canonicalForm ?p3_parLemma .
      ?p3_parLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
               ontolex:writtenRep ?p3_parWR .
