PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?sicLemmaCount ?sicLinkedLemmas ?sicItalianLemmas ?parLemmaCount ?parLinkedLemmas ?parItalianLemmas
WHERE {
  { SELECT (COUNT(DISTINCT ?s1_sicLemma) AS ?sicLemmaCount) WHERE {
        ?s1_sicLemma a lila:Lemma .
        ?s1_sicLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
        ?s1_sicLemma ontolex:writtenRep ?s1_sicWR .
    }
  }
  { SELECT (COUNT(DISTINCT ?s2_sicLemma) AS ?sicLinkedLemmas) WHERE {
        ?s2_sicLemma a lila:Lemma .
        ?s2_sicLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
        ?s2_sicLemma ontolex:writtenRep ?s2_sicWR .
      ?t2_sicEntry ontolex:canonicalForm ?s2_sicLemma .
      ?t2_itEntry vartrans:translatableAs ?t2_sicEntry .
      ?t2_itEntry ontolex:canonicalForm ?t2_liitaLemma .
      ?t2_liitaLemma ontolex:writtenRep ?t2_itLemmaString .
    }
  }
  { SELECT (COUNT(DISTINCT ?t3_liitaLemma) AS ?sicItalianLemmas) WHERE {
        ?s3_sicLemma a lila:Lemma .
        ?s3_sicLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
        ?s3_sicLemma ontolex:writtenRep ?s3_sicWR .
      ?t3_sicEntry ontolex:canonicalForm ?s3_sicLemma .
