      ?t3_itEntry ontolex:canonicalForm ?t3_liitaLemma .
      ?t3_liitaLemma ontolex:writtenRep ?t3_itLemmaString .
    }
  }
  { SELECT (COUNT(DISTINCT ?p4_parLemma) AS ?parLemmaCount) WHERE {
        ?p4_parLemma a lila:Lemma .
        ?p4_parLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> .
        ?p4_parLemma ontolex:writtenRep ?p4_parWR .
    }
  }
  { SELECT (COUNT(DISTINCT ?p5_parLemma) AS ?parLinkedLemmas) WHERE {
        ?p5_parLemma a lila:Lemma .
        ?p5_parLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> .
        ?p5_parLemma ontolex:writtenRep ?p5_parWR .
      ?t5_parEntry ontolex:canonicalForm ?p5_parLemma .
      ?t5_itEntry vartrans:translatableAs ?t5_parEntry .
      ?t5_itEntry ontolex:canonicalForm ?t5_liitaLemma .
      ?t5_liitaLemma ontolex:writtenRep ?t5_itLemmaString .
    }
  }
  { SELECT (COUNT(DISTINCT ?t6_liitaLemma) AS ?parItalianLemmas) WHERE {
        ?p6_parLemma a lila:Lemma .
        ?p6_parLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> .
        ?p6_parLemma ontolex:writtenRep ?p6_parWR .
      ?t6_parEntry ontolex:canonicalForm ?p6_parLemma .
      ?t6_itEntry vartrans:translatableAs ?t6_parEntry .
      ?t6_itEntry ontolex:canonicalForm ?t6_liitaLemma .
      ?t6_liitaLemma ontolex:writtenRep ?t6_itLemmaString .
    }
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>

SELECT DISTINCT (?a_lemmaBank AS ?lemmaBank) (?a_lemmaBankTitle AS ?lemmaBankTitle)
WHERE {
  ?a_bankLemma dcterms:isPartOf ?a_lemmaBank .
  OPTIONAL { ?a_lemmaBank dcterms:title ?a_lemmaBankTitle . }
}

