SELECT (?a_lemmaBankTitle AS ?lemmaBankTitle) (COUNT(DISTINCT ?a_bankLemma) AS ?count)
WHERE {
  ?a_bankLemma dcterms:isPartOf ?a_lemmaBank .
  OPTIONAL { ?a_lemmaBank dcterms:title ?a_lemmaBankTitle . }
}
GROUP BY ?a_lemmaBankTitle
